-- HR Analytics Project: all-in-one MySQL script
-- Creates the schema and loads all supplied synthetic dataset rows.
-- WARNING: this drops/recreates hr_analytics_project tables; use on this practice project only.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS hr_analytics_project;
USE hr_analytics_project;
DROP TABLE IF EXISTS employee_exits;
DROP TABLE IF EXISTS recruitment;
DROP TABLE IF EXISTS promotions;
DROP TABLE IF EXISTS performance_reviews;
DROP TABLE IF EXISTS attendance;
DROP TABLE IF EXISTS salary_history;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS job_roles;
DROP TABLE IF EXISTS locations;
DROP TABLE IF EXISTS departments;


CREATE TABLE departments (
  department_id INT PRIMARY KEY,
  department_name VARCHAR(100) NOT NULL UNIQUE,
  manager_employee_id INT NULL
);
CREATE TABLE job_roles (
  job_role_id INT PRIMARY KEY,
  job_title VARCHAR(100) NOT NULL,
  department_id INT NOT NULL,
  min_salary DECIMAL(12,2) NOT NULL,
  max_salary DECIMAL(12,2) NOT NULL,
  CONSTRAINT fk_job_roles_department FOREIGN KEY (department_id) REFERENCES departments(department_id)
);
CREATE TABLE locations (
  location_id INT PRIMARY KEY,
  city VARCHAR(100) NOT NULL,
  region VARCHAR(100) NOT NULL,
  country VARCHAR(100) NOT NULL
);
CREATE TABLE employees (
  employee_id INT PRIMARY KEY,
  first_name VARCHAR(80) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  email VARCHAR(160) NOT NULL UNIQUE,
  gender VARCHAR(30),
  date_of_birth DATE,
  hire_date DATE NOT NULL,
  department_id INT NOT NULL,
  job_role_id INT NOT NULL,
  location_id INT NOT NULL,
  employment_type VARCHAR(30) NOT NULL,
  employment_status VARCHAR(30) NOT NULL,
  salary DECIMAL(12,2) NOT NULL,
  manager_id INT NULL,
  CONSTRAINT fk_employees_department FOREIGN KEY (department_id) REFERENCES departments(department_id),
  CONSTRAINT fk_employees_role FOREIGN KEY (job_role_id) REFERENCES job_roles(job_role_id),
  CONSTRAINT fk_employees_location FOREIGN KEY (location_id) REFERENCES locations(location_id)
);
-- Manager foreign keys are added after all CSV files are imported.
CREATE TABLE salary_history (
  salary_history_id INT PRIMARY KEY,
  employee_id INT NOT NULL,
  effective_date DATE NOT NULL,
  salary DECIMAL(12,2) NOT NULL,
  change_reason VARCHAR(80),
  FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
);
CREATE TABLE attendance (
  attendance_id INT PRIMARY KEY,
  employee_id INT NOT NULL,
  attendance_date DATE NOT NULL,
  attendance_status VARCHAR(30) NOT NULL,
  hours_worked DECIMAL(4,2) NOT NULL DEFAULT 0,
  late_minutes INT NOT NULL DEFAULT 0,
  FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
);
CREATE TABLE performance_reviews (
  review_id INT PRIMARY KEY,
  employee_id INT NOT NULL,
  review_date DATE NOT NULL,
  rating TINYINT NOT NULL,
  reviewer_employee_id INT NOT NULL,
  comments VARCHAR(255),
  FOREIGN KEY (employee_id) REFERENCES employees(employee_id),
  FOREIGN KEY (reviewer_employee_id) REFERENCES employees(employee_id)
);
CREATE TABLE promotions (
  promotion_id INT PRIMARY KEY,
  employee_id INT NOT NULL,
  promotion_date DATE NOT NULL,
  previous_job_role_id INT NOT NULL,
  new_job_role_id INT NOT NULL,
  salary_before DECIMAL(12,2) NOT NULL,
  salary_after DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (employee_id) REFERENCES employees(employee_id),
  FOREIGN KEY (previous_job_role_id) REFERENCES job_roles(job_role_id),
  FOREIGN KEY (new_job_role_id) REFERENCES job_roles(job_role_id)
);
CREATE TABLE recruitment (
  application_id INT PRIMARY KEY,
  application_date DATE NOT NULL,
  job_role_id INT NOT NULL,
  location_id INT NOT NULL,
  candidate_source VARCHAR(80) NOT NULL,
  application_stage VARCHAR(40) NOT NULL,
  days_to_hire INT NULL,
  offered_salary DECIMAL(12,2) NULL,
  FOREIGN KEY (job_role_id) REFERENCES job_roles(job_role_id),
  FOREIGN KEY (location_id) REFERENCES locations(location_id)
);
CREATE TABLE employee_exits (
  exit_id INT PRIMARY KEY,
  employee_id INT NOT NULL,
  exit_date DATE NOT NULL,
  exit_type VARCHAR(30) NOT NULL,
  exit_reason VARCHAR(100) NOT NULL,
  eligible_for_rehire VARCHAR(10) NOT NULL,
  FOREIGN KEY (employee_id) REFERENCES employees(employee_id)
);

-- Load locations: 6 rows

-- Load departments: 8 rows

-- Load job_roles: 18 rows

-- Load employees: 10000 rows

-- Load salary_history: 20692 rows

-- Load attendance: 139714 rows

-- Load performance_reviews: 20000 rows

-- Load promotions: 1247 rows

-- Load recruitment: 18000 rows

-- Load employee_exits: 1965 rows

-- Add circular manager relationships after all employees exist.
ALTER TABLE employees ADD CONSTRAINT fk_employees_manager FOREIGN KEY (manager_id) REFERENCES employees(employee_id);
ALTER TABLE departments ADD CONSTRAINT fk_departments_manager FOREIGN KEY (manager_employee_id) REFERENCES employees(employee_id);

SET FOREIGN_KEY_CHECKS = 1;

-- Validation queries
SELECT 'locations count' AS check_name, COUNT(*) AS total_rows FROM `locations`;
SELECT 'departments count' AS check_name, COUNT(*) AS total_rows FROM `departments`;
SELECT 'job_roles count' AS check_name, COUNT(*) AS total_rows FROM `job_roles`;
SELECT 'employees count' AS check_name, COUNT(*) AS total_rows FROM `employees`;
SELECT 'salary_history count' AS check_name, COUNT(*) AS total_rows FROM `salary_history`;
SELECT 'attendance count' AS check_name, COUNT(*) AS total_rows FROM `attendance`;
SELECT 'performance_reviews count' AS check_name, COUNT(*) AS total_rows FROM `performance_reviews`;
SELECT 'promotions count' AS check_name, COUNT(*) AS total_rows FROM `promotions`;
SELECT 'recruitment count' AS check_name, COUNT(*) AS total_rows FROM `recruitment`;
SELECT 'employee_exits count' AS check_name, COUNT(*) AS total_rows FROM `employee_exits`;
